/* =========================================================================
 * main.js —— 進入點：載入資料、綁定全域控制項事件、首次渲染
 * ========================================================================= */

import { AppState, loadData } from "./state.js";
import { bindPanelToggle } from "./panel.js";
import { bindTabs, currentPage } from "./tabs.js";
import { initCalc } from "./calc.js";
import { initResource } from "./resource.js";
import { render, renderFilters, bindStarDialog, updateRangeFill } from "./render.js";

/** 全域滑桿：數值寫入 AppState.globalStars[field]；format 決定右側數值的顯示文字 */
function bindGlobalSlider(inputId, valueId, field, format = String) {
  const input = document.getElementById(inputId);
  const valueEl = document.getElementById(valueId);
  const sync = () => {
    valueEl.textContent = format(Number(input.value));
    updateRangeFill(input);
  };
  input.value = AppState.globalStars[field];
  sync();
  input.addEventListener("input", () => {
    AppState.globalStars[field] = Number(input.value);
    sync();
    render();
  });
}

async function init() {
  bindTabs();
  const loadingState = document.getElementById("loadingState");
  try {
    await loadData();
    loadingState.style.display = "none";
  } catch (err) {
    loadingState.textContent = "資料載入失敗：" + err.message;
    console.error(err);
    return;
  }

  renderFilters();
  bindPanelToggle();
  bindStarDialog();
  bindGlobalSlider("g_charStar", "g_charStar_val", "charStar", v => v + "★");
  bindGlobalSlider("g_skillLevel", "g_skillLevel_val", "skillLevel");

  document.getElementById("searchInput").addEventListener("input", render);
  document.getElementById("mainlandDataToggle").addEventListener("input", render)

  render();
  initCalc();

  // 資源地資料較大，第一次切換到該頁時才載入
  const loadResourceIfShown = (page) => { if (page === "resource") initResource(); };
  window.addEventListener("pagechange", (e) => loadResourceIfShown(e.detail));
  loadResourceIfShown(currentPage());
}

init();
