/* =========================================================================
 * tabs.js —— 頂部頁籤：切換「技能檢視」/「屬性計算」/「資源地」頁面
 * -------------------------------------------------------------------------
 * 目前頁籤記錄在網址 hash（#stats / #resource），重新整理或分享連結時會開在同一頁。
 * 切換時在 window 發出 "pagechange" 事件（detail 為頁面名稱），供需要延遲載入的頁面使用。
 * ========================================================================= */

const PAGES = {
  skills: { hash: "", title: "武將技能檢視表" },
  stats: { hash: "#stats", title: "武將屬性計算" },
  resource: { hash: "#resource", title: "資源地守軍與產出" },
};

let current = null;

/** 目前顯示中的頁面名稱 */
export const currentPage = () => current;

function pageFromHash() {
  return Object.keys(PAGES).find(key => PAGES[key].hash && PAGES[key].hash === location.hash) || "skills";
}

function showPage(page) {
  for (const key of Object.keys(PAGES)) {
    const active = key === page;
    document.getElementById("page-" + key).hidden = !active;
    const tab = document.getElementById("tab-" + key);
    tab.setAttribute("aria-selected", active);
    tab.classList.toggle("is-active", active);
    tab.tabIndex = active ? 0 : -1;
  }
  document.getElementById("pageTitle").textContent = PAGES[page].title;
  document.title = PAGES[page].title;
  if (current !== page) {
    current = page;
    window.dispatchEvent(new CustomEvent("pagechange", { detail: page }));
  }
}

export function bindTabs() {
  const tabs = [...document.querySelectorAll(".site-tab")];
  tabs.forEach((tab, i) => {
    tab.addEventListener("click", () => {
      const page = tab.dataset.page;
      // replaceState 不會觸發 hashchange，也不會讓頁面跳到錨點
      history.replaceState(null, "", PAGES[page].hash || location.pathname + location.search);
      showPage(page);
    });
    // 左右方向鍵切換頁籤（WAI-ARIA tabs 慣例）
    tab.addEventListener("keydown", (e) => {
      if (e.key !== "ArrowLeft" && e.key !== "ArrowRight") return;
      const next = tabs[(i + (e.key === "ArrowRight" ? 1 : tabs.length - 1)) % tabs.length];
      next.focus();
      next.click();
    });
  });
  window.addEventListener("hashchange", () => showPage(pageFromHash()));
  showPage(pageFromHash());
}
