/* =========================================================================
 * calc.js —— 屬性計算頁：選擇武將 → 設定等級 / 星級 → 計算基礎值並模擬配點
 * -------------------------------------------------------------------------
 * 狀態只存在這個模組內（與技能檢視頁的星級設定互不影響）；
 * 「陸服資料」開關與技能檢視頁共用同一個設定（AppState.isOverSea），兩邊會同步。
 * 每名武將的等級 / 星級 / 配點記在 localStorage（STORE_KEY），切換武將時還原；
 * 曾經分配過點數的武將會列在「最近查看」（依最後查看時間排序，只顯示一排）。
 * ========================================================================= */

import { AppState, HERO_STAR_MIN, HERO_STAR_MAX, HERO_LEVEL_MIN, GRADIENT_LABELS } from "./state.js";
import { getAllHeroesAndSkills, HERO_STATS, getLevelAttrPoints, getStarAttrPoints, getHeroBaseStats } from "./core.js";
import { render, updateRangeFill } from "./render.js";

const calc = {
  heroId: null,
  level: null,   // null = 該武將的等級上限
  star: HERO_STAR_MAX,
  alloc: Object.fromEntries(HERO_STATS.map(s => [s.key, 0])),
};

let heroes = [];

/* ---------------- 每名武將的設定存檔 ---------------- */

// localStorage：{ [heroId]: { level, star, alloc: { force, ... }, allocated, t } }
//   level 為 null 代表跟隨等級上限；allocated 表示曾經分配過點數；t 為最後查看時間
const STORE_KEY = "calcHeroes";

function loadStore() {
  try {
    const parsed = JSON.parse(localStorage.getItem(STORE_KEY) || "{}");
    return parsed && typeof parsed === "object" ? parsed : {};
  } catch { return {}; }
}

let store = loadStore();

function saveStore() {
  try { localStorage.setItem(STORE_KEY, JSON.stringify(store)); } catch { /* 無法存取 storage 時只在本次瀏覽有效 */ }
}

/** 使用者調整等級 / 星級 / 配點後呼叫：寫入目前武將的設定 */
function persist() {
  if (!calc.heroId) return;
  const prev = store[calc.heroId];
  store[calc.heroId] = {
    level: calc.level,
    star: calc.star,
    alloc: { ...calc.alloc },
    allocated: Boolean(prev?.allocated) || usedPoints() > 0,
    t: Date.now(),
  };
  saveStore();
  renderRecent();
}

const $ = (id) => document.getElementById(id);

/** 屬性數值顯示：四捨五入到小數 1 位（同遊戲 HERO_ATTR_DISPLAY_PRECISION） */
const fmt = (v) => String(Math.round(v * 10) / 10);
/** 成長值顯示：最多兩位小數 */
const fmtGrow = (v) => String(Number(v.toFixed(2)));

function escapeHtml(str) {
  const div = document.createElement("div");
  div.textContent = str;
  return div.innerHTML;
}

const currentHero = () => heroes.find(h => h.heroId === calc.heroId);
const maxLevel = () => AppState.heroes[calc.heroId]?.LvMax || 50;
const effectiveLevel = () => Math.min(calc.level ?? maxLevel(), maxLevel());
/** 可分配點數來源：等級 / 星級 */
function pointSources() {
  if (!calc.heroId) return { level: 0, star: 0 };
  return {
    level: getLevelAttrPoints(effectiveLevel()),
    star: getStarAttrPoints(calc.heroId, calc.star),
  };
}
const totalPoints = () => Object.values(pointSources()).reduce((a, b) => a + b, 0);
const usedPoints = () => HERO_STATS.reduce((sum, s) => sum + calc.alloc[s.key], 0);

/** 總點數變少（降級 / 降星 / 切換資料版本）時，由後往前扣回超出的配點 */
function clampAlloc() {
  let over = usedPoints() - totalPoints();
  for (const stat of [...HERO_STATS].reverse()) {
    if (over <= 0) break;
    const cut = Math.min(over, calc.alloc[stat.key]);
    calc.alloc[stat.key] -= cut;
    over -= cut;
  }
}

/* ---------------- 步驟 1：武將清單 ---------------- */

function makeHeroButton(hero) {
  const btn = document.createElement("button");
  btn.type = "button";
  btn.className = "calc-hero";
  btn.setAttribute("role", "option");
  btn.dataset.heroId = hero.heroId;
  btn.dataset.name = String(hero.name).toLowerCase();
  btn.innerHTML = `
    <img src="${hero.iconUrl}" alt="" loading="lazy" decoding="async" />
    <span class="calc-hero-name">${escapeHtml(hero.name)}</span>`;
  btn.addEventListener("click", () => selectHero(hero.heroId));
  return btn;
}

function renderHeroGrid() {
  const grid = $("calcHeroGrid");
  grid.innerHTML = "";
  for (const hero of heroes) grid.appendChild(makeHeroButton(hero));
  syncHeroGrid();
}

/** 最近查看：曾經分配過點數的武將，依最後查看時間由新到舊 */
function renderRecent() {
  const list = heroes
    .filter(h => store[h.heroId]?.allocated)
    .sort((a, b) => (store[b.heroId].t || 0) - (store[a.heroId].t || 0));
  $("calcRecentGroup").hidden = list.length === 0;
  const grid = $("calcRecent");
  grid.innerHTML = "";
  for (const hero of list) grid.appendChild(makeHeroButton(hero));
  fitRecentRow();
  syncHeroGrid();
}

/** 最近查看只顯示一排：依目前欄數隱藏超出的武將（隱藏的按鈕也不會被 Tab 選到） */
function fitRecentRow() {
  const grid = $("calcRecent");
  const cols = getComputedStyle(grid).gridTemplateColumns.split(" ").filter(Boolean).length;
  if (!cols || grid.offsetParent === null) return;  // 頁面隱藏中，等顯示時 ResizeObserver 會再呼叫
  [...grid.children].forEach((btn, i) => { btn.hidden = i >= cols; });
}

function syncHeroGrid() {
  const query = $("calcSearch").value.trim().toLowerCase();
  const mark = (btn) => {
    const selected = btn.dataset.heroId === calc.heroId;
    btn.classList.toggle("is-selected", selected);
    btn.setAttribute("aria-selected", selected);
  };
  for (const btn of $("calcRecent").children) mark(btn);
  for (const btn of $("calcHeroGrid").children) {
    mark(btn);
    btn.hidden = Boolean(query) && !btn.dataset.name.includes(query);
  }
}

function selectHero(heroId) {
  if (calc.heroId === heroId) return;
  calc.heroId = heroId;
  const saved = store[heroId];
  if (saved) {
    // 還原這名武將上次的設定，並更新最後查看時間
    calc.level = saved.level ?? null;
    if (Number.isInteger(saved.star)) calc.star = Math.max(HERO_STAR_MIN, Math.min(HERO_STAR_MAX, saved.star));
    for (const stat of HERO_STATS) calc.alloc[stat.key] = Math.max(0, Math.floor(saved.alloc?.[stat.key]) || 0);
    saved.t = Date.now();
    saveStore();
  } else {
    // 沒有存檔：等級跟隨上限、清空配點，星級沿用目前設定
    calc.level = null;
    for (const stat of HERO_STATS) calc.alloc[stat.key] = 0;
  }
  syncStarSlider();
  renderRecent();
  update();
}

/* ---------------- 步驟 2：等級 / 星級 ---------------- */

function syncStarSlider() {
  const input = $("calcStar");
  input.min = HERO_STAR_MIN;
  input.max = HERO_STAR_MAX;
  input.value = calc.star;
  $("calcStarVal").textContent = calc.star + "★";
  updateRangeFill(input);
}

function syncLevelSlider() {
  const input = $("calcLevel");
  input.min = HERO_LEVEL_MIN;
  input.max = maxLevel();
  input.value = effectiveLevel();
  $("calcLevelVal").textContent = input.value;
  updateRangeFill(input);
}

/* ---------------- 步驟 3：屬性結果 / 配點 ---------------- */

/** 建立結果區的骨架（每次換武將時重建），數值由 update() 填入 */
function renderResultShell() {
  const result = $("calcResult");
  const hero = currentHero();
  if (!hero) {
    result.innerHTML = `<div class="calc-empty">請先在上方選擇武將</div>`;
    return;
  }

  const gradient = GRADIENT_LABELS[hero.gradient];
  result.innerHTML = `
    <div class="calc-summary">
      <div class="calc-hero-info">
        <img src="${hero.iconUrl}" alt="" />
        <div>
          <div class="calc-hero-title">${escapeHtml(hero.name)}
            ${gradient ? `<span class="meta-tag gradient-${hero.gradient}">${gradient}</span>` : ""}
          </div>
          <div class="calc-hero-sub" data-ref="sub"></div>
        </div>
      </div>
      <div class="calc-points">
        <div class="calc-points-num"><b data-ref="remain"></b><span>/ <span data-ref="total"></span></span></div>
        <div class="calc-points-label">剩餘可分配點數</div>
        <div class="calc-points-src" data-ref="src"></div>
      </div>
      <button type="button" class="reset-btn" data-ref="reset">重置配點</button>
    </div>
    <div class="calc-stats">
      ${HERO_STATS.map(stat => `
        <div class="calc-stat stat-${stat.key}" data-stat="${stat.key}">
          <div class="calc-stat-head">
            <span class="calc-stat-label">${stat.label}</span>
            <span class="calc-stat-final" data-ref="final"></span>
          </div>
          <div class="calc-stat-bar"><span class="bar-base" data-ref="barBase"></span><span class="bar-alloc" data-ref="barAlloc"></span></div>
          <div class="calc-stat-detail">
            <span>基礎 <b data-ref="base"></b> <small data-ref="grow"></small></span>
            <span class="calc-alloc">
              <span class="calc-alloc-label">配點</span>
              <span class="stepper sm">
                <button type="button" data-ref="minus" aria-label="${stat.label}減 1">－</button>
                <input type="number" class="calc-alloc-input" data-ref="input" min="0" step="1" inputmode="numeric" aria-label="${stat.label}配點" />
                <button type="button" data-ref="plus" aria-label="${stat.label}加 1">＋</button>
              </span>
              <button type="button" class="calc-alloc-max" data-ref="max">全加</button>
            </span>
          </div>
        </div>`).join("")}
    </div>`;

  const ref = (root, name) => root.querySelector(`[data-ref="${name}"]`);
  ref(result, "reset").addEventListener("click", () => {
    for (const stat of HERO_STATS) calc.alloc[stat.key] = 0;
    update();
    persist();
  });

  for (const stat of HERO_STATS) {
    const row = result.querySelector(`[data-stat="${stat.key}"]`);
    const setAlloc = (v) => {
      const cap = calc.alloc[stat.key] + totalPoints() - usedPoints();
      calc.alloc[stat.key] = Math.max(0, Math.min(cap, Math.floor(v) || 0));
      update();
      persist();
    };
    ref(row, "minus").addEventListener("click", () => setAlloc(calc.alloc[stat.key] - 1));
    ref(row, "plus").addEventListener("click", () => setAlloc(calc.alloc[stat.key] + 1));
    ref(row, "max").addEventListener("click", () => setAlloc(Infinity));
    const input = ref(row, "input");
    input.addEventListener("input", () => setAlloc(Number(input.value)));
    // 輸入中不改寫欄位內容，離開欄位時再顯示修正後的數值
    input.addEventListener("change", () => { input.value = calc.alloc[stat.key]; });
  }
}

/** 依目前狀態更新所有數值（不重建 DOM，輸入框才不會失去焦點） */
function update() {
  syncLevelSlider();
  const result = $("calcResult");
  if (!calc.heroId) return;
  if (!result.querySelector(".calc-stats") || result.dataset.heroId !== calc.heroId) {
    renderResultShell();
    result.dataset.heroId = calc.heroId;
  }

  clampAlloc();
  const level = effectiveLevel();
  const total = totalPoints();
  const remain = total - usedPoints();
  const base = getHeroBaseStats(calc.heroId, level);
  const hero = AppState.heroes[calc.heroId];
  const finals = HERO_STATS.map(s => base[s.key] + calc.alloc[s.key]);
  const scale = Math.max(1, ...finals);

  const ref = (root, name) => root.querySelector(`[data-ref="${name}"]`);
  ref(result, "sub").textContent = `Lv.${level} · ${calc.star}★ · ${AppState.isOverSea ? "陸服" : "海外"}資料`;
  ref(result, "remain").textContent = remain;
  ref(result, "total").textContent = total;
  const src = pointSources();
  ref(result, "src").textContent = `等級 ${src.level} + 星級 ${src.star}`;
  result.querySelector(".calc-points").classList.toggle("is-done", total > 0 && remain === 0);

  HERO_STATS.forEach((stat, i) => {
    const row = result.querySelector(`[data-stat="${stat.key}"]`);
    const alloc = calc.alloc[stat.key];
    ref(row, "final").textContent = fmt(finals[i]);
    ref(row, "base").textContent = fmt(base[stat.key]);
    ref(row, "grow").textContent = `(+${fmtGrow(hero[stat.grow] || 0)}/級)`;
    ref(row, "barBase").style.width = (base[stat.key] / scale) * 100 + "%";
    ref(row, "barAlloc").style.width = (alloc / scale) * 100 + "%";
    const input = ref(row, "input");
    input.max = alloc + remain;
    if (document.activeElement !== input) input.value = alloc;
    ref(row, "minus").disabled = alloc <= 0;
    ref(row, "plus").disabled = remain <= 0;
    ref(row, "max").disabled = remain <= 0;
  });
}

/* ---------------- 初始化 ---------------- */

export function initCalc() {
  heroes = getAllHeroesAndSkills();
  renderHeroGrid();
  renderRecent();
  syncStarSlider();
  renderResultShell();
  syncLevelSlider();
  new ResizeObserver(fitRecentRow).observe($("calcRecent"));

  $("calcSearch").addEventListener("input", syncHeroGrid);

  $("calcStar").addEventListener("input", (e) => {
    calc.star = Number(e.target.value);
    syncStarSlider();
    update();
    persist();
  });

  $("calcLevel").addEventListener("input", (e) => {
    calc.level = Number(e.target.value);
    update();
    persist();
  });

  // 「陸服資料」開關與技能檢視頁同步
  const mainToggle = $("mainlandDataToggle");
  const calcToggle = $("calcMainlandToggle");
  calcToggle.checked = mainToggle.checked;
  calcToggle.addEventListener("input", () => {
    mainToggle.checked = calcToggle.checked;
    render();  // render() 會依開關更新 AppState.isOverSea
    update();
  });
  mainToggle.addEventListener("input", () => {
    calcToggle.checked = mainToggle.checked;
    update();
  });

  // 重新開啟頁面時，自動選回最近查看的武將
  const last = Object.keys(store)
    .filter(id => heroes.some(h => h.heroId === id))
    .sort((a, b) => (store[b].t || 0) - (store[a].t || 0))[0];
  if (last) selectHero(last);
}
