/* =========================================================================
 * render.js —— 畫面渲染：角色列表 / 展開內容 / 圖示 / stepper
 * ========================================================================= */

import {
  AppState, SKILL_STAR_MIN, SKILL_STAR_MAX,
  WEAPON_LEVEL_MIN, WEAPON_LEVEL_MAX,
  getSkillEffectiveStar, setSkillStarOverride,
  getWeaponEffectiveLevel, setWeaponLevelOverride,
  resetHeroOverride, heroHasCustom, GRADIENT_LABELS,
} from "./state.js";
import { updatePanelToggle } from "./panel.js";
import { getAllHeroesAndSkills, formatSkillDescription, formatWeaponDescription, getSkillById, getWeaponByHeroId, getHeroStarEffects } from "./core.js";

let openHeroId = null;

// 列表最前面幾個角色的圖示直接載入（首屏），其餘圖示延遲到接近可視範圍才下載
const EAGER_ICON_COUNT = 12;

// 兵種適性：HeroSoliderGrade 的 index 0 / 1 / 3 分別對應盾 / 弓 / 騎，數值 1~4 = S/A/B/C
const SOLDIER_TYPES = [[0, "盾"], [1, "弓"], [3, "騎"]];
const SOLDIER_GRADE_LABELS = { 1: "S", 2: "A", 3: "B", 4: "C" };

/** 英雄名稱右方的資訊標籤：預計推出賽季 / 稀有度 / 兵種適性 */
function renderHeroMeta(hero) {
  const parts = [];
  if (hero.gradient in GRADIENT_LABELS) {
    parts.push(`<span class="meta-tag gradient-${hero.gradient}">${GRADIENT_LABELS[hero.gradient]}</span>`);
  }
  if (hero.season != null) {
    parts.push(`<span class="meta-tag season">S${hero.season}</span>`);
  }
  const grades = SOLDIER_TYPES
    .filter(([idx]) => SOLDIER_GRADE_LABELS[hero.soldierGrade[idx]])
    .map(([idx, label]) => {
      const g = SOLDIER_GRADE_LABELS[hero.soldierGrade[idx]];
      return `<span class="soldier-grade grade-${g}">${label}<b>${g}</b></span>`;
    });
  if (grades.length) parts.push(`<span class="soldier-grades">${grades.join("")}</span>`);
  return `<span class="hero-meta">${parts.join("")}</span>`;
}

function escapeHtml(str) {
  const div = document.createElement("div");
  div.textContent = str;
  return div.innerHTML;
}

// 圖示節點快取：key 為圖示所在位置（角色 / 技能），重繪時沿用同一個已載入、已解碼的節點，
// 避免 render() 重建列表時 <img> 被重新建立而閃爍
const iconCache = new Map();

/** 回傳圖示元素（.icon-layered）；同一個 cacheKey 且網址不變時回傳上次建立的同一個節點 */
function renderIconWithStars(cacheKey, iconUrl, name, size = "", eager = false) {
  const cached = iconCache.get(cacheKey);
  if (cached && cached.dataset.src === (iconUrl || "")) return cached;

  const wrap = document.createElement("div");
  wrap.className = "icon-layered" + (size === "sm" ? " sm" : "");
  wrap.dataset.src = iconUrl || "";

  if (iconUrl) {
    const img = document.createElement("img");
    // loading="lazy"：收合中（display:none）的技能圖示不會下載，展開時才載入
    if (eager) img.fetchPriority = "high";
    else img.loading = "lazy";
    img.decoding = "async";
    img.alt = name ?? "";
    img.src = iconUrl;
    wrap.appendChild(img);
  } else {
    wrap.innerHTML = `<div class="icon-placeholder-text">${escapeHtml(name ?? "").slice(0, 4)}</div>`;
  }

  iconCache.set(cacheKey, wrap);
  return wrap;
}

/** 更新 <input type=range> 的填色比例（--pct），讓現代化滑桿樣式生效 */
function updateRangeFill(input) {
  const min = Number(input.min), max = Number(input.max), val = Number(input.value);
  const pct = max > min ? ((val - min) / (max - min)) * 100 : 0;
  input.style.setProperty("--pct", pct + "%");
}

/** 滑桿元件（用於技能等級全域預設值） */
function makeMiniSlider({ labelText, swatchClass, value, min, max, onChange }) {
  const wrap = document.createElement("div");
  wrap.className = "mini-slider-item";
  wrap.innerHTML = `
    <div class="label-row">
      <span class="name"><span class="swatch ${swatchClass}"></span>${labelText}</span>
      <span class="value">${value}</span>
    </div>
    <input type="range" class="mini" min="${min}" max="${max}" step="1" value="${value}">
  `;
  const input = wrap.querySelector("input");
  const valueEl = wrap.querySelector(".value");
  updateRangeFill(input);
  input.addEventListener("input", () => {
    valueEl.textContent = input.value;
    updateRangeFill(input);
    onChange(Number(input.value));
  });
  return wrap;
}

/** +/- 一級一級調整的 stepper 元件（用於技能星級 / 專武等級） */
function makeStepper({ value, min, max, onChange, size = "" }) {
  const wrap = document.createElement("div");
  wrap.className = "stepper" + (size === "sm" ? " sm" : "");

  const minusBtn = document.createElement("button");
  minusBtn.type = "button";
  minusBtn.textContent = "－";
  const valueEl = document.createElement("span");
  valueEl.className = "value";
  valueEl.textContent = value;
  const plusBtn = document.createElement("button");
  plusBtn.type = "button";
  plusBtn.textContent = "＋";

  const fixNum = max === 6 ? 1 : 0;
  const star = max === 6 ? "★" : "";
  function refresh(v) {
    valueEl.textContent = (v - fixNum) + star;
    minusBtn.disabled = v <= min;
    plusBtn.disabled = v >= max;
  }
  refresh(value);

  let showValue = valueEl.textContent;
  if (max === 6) {
    showValue = showValue.substring(0, showValue.length - 1)
  }

  minusBtn.addEventListener("click", () => {
    const next = Math.max(min, Number(showValue) - 1 + fixNum);
    refresh(next);
    onChange(next);
  });
  plusBtn.addEventListener("click", () => {
    const next = Math.min(max, Number(showValue) + 1 + fixNum);
    refresh(next);
    onChange(next);
  });

  wrap.appendChild(minusBtn);
  wrap.appendChild(valueEl);
  wrap.appendChild(plusBtn);
  return wrap;
}

export function render() {
  const searchInput = document.getElementById("searchInput");
  const query = searchInput.value.trim().toLowerCase();
  const heroList = document.getElementById("heroList");
  const emptyState = document.getElementById("emptyState");

  const showChinaData = document.getElementById("mainlandDataToggle");
  AppState.isOverSea = showChinaData.checked;

  const heroes = getAllHeroesAndSkills();
  const skillMap = new Map(heroes.flatMap(hero => hero.skillIds.map(id => [id, getSkillById(id)])));

  // 名稱欄寬取全部武將中最長的名稱（以字數 × 1em 估算中文字寬），讓後方標籤對齊；
  // 以全部武將計算而非篩選結果，切換篩選時對齊位置才不會跳動
  const nameChars = Math.max(0, ...heroes.map(hero => [...String(hero.name)].length));
  heroList.style.setProperty("--hero-name-width", nameChars + "em");

  const { gradientFilter, seasonFilter } = AppState;
  const filtered = heroes.filter(hero => {
    if (gradientFilter.size && !gradientFilter.has(hero.gradient)) return false;
    if (seasonFilter.size && !seasonFilter.has(hero.season)) return false;
    if (!query) return true;
    if (hero.name.toLowerCase().includes(query)) return true;

    return hero.skillIds.some(id => {
      const s = getSkillById(id);
      const name = AppState.strings[s.Name] || "";
      return name.toLowerCase().includes(query);
    });
  });

  updatePanelToggle();

  heroList.innerHTML = "";
  emptyState.style.display = filtered.length === 0 ? "block" : "none";

  filtered.forEach((hero, index) => {
    const isOpen = hero.heroId === openHeroId;
    const heroCharStar = AppState.globalStars.charStar; // 英雄星級全域共用，不再逐一覆寫

    const card = document.createElement("div");
    card.className = "hero-card" + (isOpen ? " open" : "");

    const heroIcon = renderIconWithStars("hero:" + hero.heroId, hero.iconUrl, hero.name, "", index < EAGER_ICON_COUNT);

    const head = document.createElement("div");
    head.className = "hero-head";
    head.innerHTML = `
      <span class="expand-arrow">▶</span>
      <span class="hero-name">${escapeHtml(hero.name)}</span>
      ${renderHeroMeta(hero)}
      <span class="hero-head-spacer"></span>
      <button type="button" class="star-fx-btn" aria-label="${escapeHtml(hero.name)} 星級增益"><span class="star-fx-icon">★</span>星級增益</button>
      <span class="hero-id">#${hero.heroId}</span>
    `;
    head.insertBefore(heroIcon, head.querySelector(".hero-name"));
    head.querySelector(".star-fx-btn").addEventListener("click", (e) => {
      e.stopPropagation();  // 不觸發展開 / 收合
      openStarDialog(hero);
    });

    // 先隱藏後續再處理
    // if (heroHasCustom(hero.heroId)) {
    //   const tag = document.createElement("span");
    //   tag.className = "custom-tag";
    //   tag.textContent = "已自訂";
    //   head.appendChild(tag);
    // }
    head.addEventListener("click", (e) => {
      if (e.target.closest(".reset-btn")) return;
      openHeroId = isOpen ? null : hero.heroId;
      render();
    });
    card.appendChild(head);

    const body = document.createElement("div");
    body.className = "hero-body";

    const skillsTitle = document.createElement("div");
    skillsTitle.className = "section-title";
    skillsTitle.textContent = "技能／專武";
    body.appendChild(skillsTitle);

    // ---- 每個技能：icon 下方顯示目前星級 + stepper 獨立調整 ----
    hero.skillIds.forEach(skillId => {
      const skill = skillMap.get(skillId);
      if (!skill) return;

      let skillStar = getSkillEffectiveStar(hero.heroId, skillId);
      const maxLevel = skill.LevelMax !== undefined ? skill.LevelMax : 10;
      if (skillStar > maxLevel) skillStar = maxLevel;

      let skillIcon = skill.SkillIcon
      if (maxLevel == 6) skillIcon = Number(hero.heroId)+50000;

      const skillIconUrl = "assets\\skill\\" + skillIcon + ".webp";  // 技能圖示路徑
      const skillIconEl = renderIconWithStars(`skill:${hero.heroId}:${skillId}`, skillIconUrl, skill.name, "sm");
      const effective = { charStar: heroCharStar, skillStar: skillStar };
      const descHtml = formatSkillDescription(skillId, effective);

      const row = document.createElement("div");
      row.className = "skill-row";

      const iconCol = document.createElement("div");
      iconCol.className = "skill-icon-col";
      iconCol.appendChild(skillIconEl);
      iconCol.appendChild(makeStepper({
        value: skillStar, min: SKILL_STAR_MIN, max: maxLevel, size: "sm",
        onChange: (v) => { setSkillStarOverride(hero.heroId, skillId, v); render(); },
      }));

      const skillName = AppState.strings[skill.SkillName] || skill.name;
      const textCol = document.createElement("div");
      textCol.className = "skill-text";
      textCol.innerHTML = `
        <div class="skill-name-row">
          <span class="skill-name">${escapeHtml(skillName)}</span>
          <span class="skill-id">#${skillId}</span>
        </div>
        <div class="skill-desc">${descHtml}</div>
      `;

      row.appendChild(iconCol);
      row.appendChild(textCol);
      body.appendChild(row);
    });

    // ---- 專武：併入技能清單，用同一套 icon + stepper 呈現 ----
    if (hero.weaponId) {
      const weapon_info = getWeaponByHeroId(hero.heroId);
      const weapon = getSkillById(hero.weaponId);
      if (weapon) {
        let weaponLevel = getSkillEffectiveStar(hero.heroId, hero.weaponId);  // 專武等級（每個角色各自記錄自己的專武等級）
        if (weaponLevel > weapon.LevelMax) weaponLevel = weapon.LevelMax; // clamp to max 5
        const weaponIconUrl = "assets\\skill\\" + weapon.SkillIcon + ".webp";  // 專武圖示路徑
        const weaponIcon = renderIconWithStars("weapon:" + hero.heroId, weaponIconUrl, weapon.name, "sm");
        const effective = { charStar: heroCharStar, skillStar: weaponLevel };
        const descHtml = formatSkillDescription(hero.weaponId, effective);

        const row = document.createElement("div");
        row.className = "skill-row";

        const iconCol = document.createElement("div");
        iconCol.className = "skill-icon-col";
        iconCol.appendChild(weaponIcon);
        iconCol.appendChild(makeStepper({
          value: weaponLevel, min: WEAPON_LEVEL_MIN, max: weapon.LevelMax, size: "sm",
          onChange: (v) => { setSkillStarOverride(hero.heroId, hero.weaponId, v); render(); },
        }));

        const weaponName = AppState.strings[weapon_info.Name] || weapon.name;
        const textCol = document.createElement("div");
        textCol.className = "skill-text";
        textCol.innerHTML = `
          <div class="skill-name-row">
            <span class="weapon-tag">專武</span>
            <span class="skill-name">${escapeHtml(weaponName)}</span>
            <span class="skill-id">#${hero.weaponId}</span>
          </div>
          <div class="skill-desc">${descHtml}</div>
        `;

        row.appendChild(iconCol);
        row.appendChild(textCol);
        body.appendChild(row);
      }
    }

    card.appendChild(body);
    heroList.appendChild(card);
  });
}

/** 篩選按鈕列：可複選，全部不選 = 顯示全部；options 為 [[value, label, extraClass?], ...] */
function renderChipFilter(containerId, filter, options) {
  const container = document.getElementById(containerId);
  container.innerHTML = "";

  const makeBtn = (text, selected, onClick, extraClass = "") => {
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "filter-chip " + extraClass + (selected ? " is-selected" : "");
    btn.textContent = text;
    btn.addEventListener("click", () => {
      onClick();
      renderFilters();
      render();
    });
    container.appendChild(btn);
  };

  makeBtn("全部", filter.size === 0, () => filter.clear());
  for (const [value, label, extraClass] of options) {
    makeBtn(label, filter.has(value), () => {
      if (filter.has(value)) filter.delete(value);
      else filter.add(value);
    }, extraClass);
  }
}

/** 頂部篩選按鈕：稀有度 / 預計推出賽季 */
export function renderFilters() {
  renderChipFilter("g_gradient_filter", AppState.gradientFilter,
    Object.entries(GRADIENT_LABELS).map(([g, label]) => [Number(g), label, "gradient-" + g]));

  const seasons = [...new Set(getAllHeroesAndSkills().map(h => h.season))]
    .filter(v => v != null)
    .sort((a, b) => a - b);
  renderChipFilter("g_season_filter", AppState.seasonFilter,
    seasons.map(v => [v, "S" + v, "season"]));
}

/* -------------------------------------------------------------------------
 * 星級效果彈出視窗：以清單列出 1~5 星各自獲得的增益
 * ------------------------------------------------------------------------- */

/** 星級效果清單的 HTML（tools/prune-data.mjs 也會呼叫，確保用到的字串不被精簡掉） */
export function renderStarEffectsHtml(hero) {
  const currentStar = AppState.globalStars.charStar;
  return getHeroStarEffects(hero.heroId).map(effect => {
    const items = [];
    if (effect.attrPoint) {
      items.push(`<span class="star-fx-attr">屬性點 <b>+${effect.attrPoint}</b></span>`);
    }
    for (const skill of effect.skills) {
      items.push(`<div class="star-fx-skill">${skill.html}</div>`);
    }
    if (!items.length) items.push(`<span class="star-fx-none">無額外增益</span>`);

    return `
      <li class="star-fx-row${effect.star <= currentStar ? " is-reached" : ""}">
        <span class="star-fx-level">${effect.star}<small>★</small></span>
        <div class="star-fx-items">${items.join("")}</div>
      </li>`;
  }).join("");
}

function openStarDialog(hero) {
  const dialog = document.getElementById("starDialog");
  document.getElementById("starDialogTitle").textContent = hero.name + "・星級效果";
  document.getElementById("starDialogVersion").textContent = AppState.isOverSea ? "陸服" : "海外";
  document.getElementById("starDialogList").innerHTML = renderStarEffectsHtml(hero);
  dialog.showModal();
}

/** 綁定彈出視窗的關閉操作（Esc 由 <dialog> 內建處理） */
export function bindStarDialog() {
  const dialog = document.getElementById("starDialog");
  dialog.querySelector(".star-dialog-close").addEventListener("click", () => dialog.close());
  // 點擊視窗外的背景關閉
  dialog.addEventListener("click", (e) => {
    if (e.target === dialog) dialog.close();
  });
}

export { updateRangeFill };
