/* =========================================================================
 * resource.js —— 資源地頁：各等級自然 / 屯田產出 + 守軍資料
 * -------------------------------------------------------------------------
 * 資料：data/resource_ground.json（由 lua/dump_resource.lua 從遊戲資料匯出），
 *       第一次切換到此頁時才載入。
 * 計算規則對照遊戲 lua：
 *   自然產出：ResourceGroundSeason 各資源分頁的 Production（每小時）
 *   屯田一次：ceil(每小時產出 × outputSec / 3600)（panel/resGround/HoardChoose.lua，不含科技 / 同盟加成）
 *   守軍：npc[等級] 決定 NPC 等級與隊數，NPCResource[NPC 等級][兵種] 決定兵數與武將
 *         （兵種組合各賽季相同：1~2 級 1 隊、3 級起 2 隊，每日依位置隨機，頁面不另外列出）
 * ========================================================================= */

import { AppState } from "./state.js";
import { getSkillById } from "./core.js";

const DEFAULT_SEASON = "3";  // 台服目前 S2 使用陸服 S3 劇本
const SEASON_KEY = "resourceSeason";
const PRODUCTION_OPEN_KEY = "resourceProductionOpen";
const RES_TYPES = ["1", "2", "3", "4"];  // 農田 / 林場 / 石場 / 銅礦
// 兵種類別（NPCResource 的鍵）：1 盾 / 2 弓 / 4 騎
const SOLDIER_KIND_LABELS = { 1: "盾", 2: "弓", 4: "騎" };
const HERO_SLOT_LABELS = ["主將", "副將", "副將"];

let data = null;
let loading = null;
let season = DEFAULT_SEASON;
try { season = localStorage.getItem(SEASON_KEY) || DEFAULT_SEASON; } catch { /* 無法存取 storage 時用預設值 */ }

const $ = (id) => document.getElementById(id);
const str = (id) => AppState.strings[id] ?? String(id);
const num = (v) => Number(v).toLocaleString("en-US");

function escapeHtml(text) {
  const div = document.createElement("div");
  div.textContent = text;
  return div.innerHTML;
}

const sortedLevels = (obj) => Object.keys(obj).map(Number).filter(lv => lv > 0).sort((a, b) => a - b);

/* ---------------- 賽季切換 ---------------- */

function renderSeasonChips() {
  const container = $("resSeasonFilter");
  container.innerHTML = "";
  const seasons = Object.keys(data.seasons).map(Number).sort((a, b) => a - b);
  for (const s of seasons) {
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "filter-chip season" + (String(s) === season ? " is-selected" : "");
    btn.textContent = "S" + s;
    btn.addEventListener("click", () => {
      season = String(s);
      try { localStorage.setItem(SEASON_KEY, season); } catch { /* 忽略 */ }
      renderSeasonChips();
      renderAll();
    });
    container.appendChild(btn);
  }
}

/* ---------------- 產出 ---------------- */

function renderProduction(sd) {
  const { production, names } = sd;
  const levels = sortedLevels(production);
  const hours = data.tuntian.outputSec / 3600;
  const hoard = (rate) => Math.ceil(rate * hours);

  // 四種資源地產量相同時合併成一欄，不同時分開顯示
  const same = levels.every(lv => new Set(RES_TYPES.map(t => production[lv][t])).size === 1);
  const columns = same ? [{ label: RES_TYPES.map(t => str(names[t])).join("／"), type: RES_TYPES[0] }]
    : RES_TYPES.map(t => ({ label: str(names[t]), type: t }));

  const head = columns.length === 1
    ? `<tr><th>等級</th><th>自然產出<small>每小時</small></th><th>屯田一次<small>${hours} 小時產量</small></th></tr>`
    : `<tr><th rowspan="2">等級</th>${columns.map(c => `<th colspan="2">${escapeHtml(c.label)}</th>`).join("")}</tr>
       <tr>${columns.map(() => `<th>自然<small>每小時</small></th><th>屯田<small>一次</small></th>`).join("")}</tr>`;

  const rows = levels.map(lv => `
    <tr>
      <td class="res-lv">Lv.${lv}</td>
      ${columns.map(c => {
        const rate = production[lv][c.type] || 0;
        return `<td>${num(rate)}</td><td class="res-hoard">${num(hoard(rate))}</td>`;
      }).join("")}
    </tr>`).join("");

  const t = data.tuntian;
  $("resProduction").innerHTML = `
    ${same ? `<p class="res-sub">${escapeHtml(columns[0].label)}各等級產量相同</p>` : ""}
    <div class="res-table-wrap">
      <table class="res-table">
        <thead>${head}</thead>
        <tbody>${rows}</tbody>
      </table>
    </div>
    <p class="calc-note">
      屯田每次消耗 ${t.cost} 張策書，獲得 ${hours} 小時的自然產量；策書上限 ${t.maxCnt} 張，每 ${t.recover[0] / 3600} 小時回復 ${t.recover[1]} 張，每日可購買 ${t.buyCnt} 次。<br />
      表中數值未含科技與同盟加成。
    </p>`;
}

/* ---------------- 守軍 ---------------- */

/** 位置標籤：例如 [0, 1, 2] → 「主將＋副將 ×2」 */
function slotLabel(slots) {
  const counts = new Map();
  for (const i of slots) {
    const label = HERO_SLOT_LABELS[i] || "副將";
    counts.set(label, (counts.get(label) || 0) + 1);
  }
  return [...counts].map(([label, n]) => (n > 1 ? `${label} ×${n}` : label)).join("＋");
}

/** 依數值合併守將：回傳 [{ hero, slots }]，維持主將在前的順序 */
function groupHeroes(sd, heroIds) {
  const groups = new Map();
  heroIds.forEach((id, i) => {
    const hero = sd.heroes[id];
    if (!hero) return;
    const key = JSON.stringify(hero);
    if (!groups.has(key)) groups.set(key, { hero, slots: [] });
    groups.get(key).slots.push(i);
  });
  return [...groups.values()];
}

/** slots：此守將出現的位置（0 主將、1 / 2 副將），數值完全相同的守將合併成一張 */
function renderHero(hero, slots) {
  const skills = hero.skills.map(sk => {
    const skill = getSkillById(sk.id);
    const name = skill ? str(skill.SkillName) : "#" + sk.id;
    return `<span class="res-skill">${escapeHtml(name)} <b>Lv.${sk.lv}</b></span>`;
  }).join("");
  return `
    <div class="res-hero">
      <img src="assets/hero/normal/${hero.icon}.webp" alt="" loading="lazy" decoding="async" />
      <div class="res-hero-main">
        <div class="res-hero-name">
          <span class="res-slot">${slotLabel(slots)}</span>
          ${escapeHtml(str(hero.name))}
          <span class="res-hero-lv">Lv.${hero.lv} · ${hero.star}★</span>
        </div>
        <div class="res-hero-stats">
          <span>武力 <b>${hero.force}</b></span><span>智力 <b>${hero.brain}</b></span>
          <span>統帥 <b>${hero.com}</b></span><span>防禦 <b>${hero.def}</b></span>
        </div>
        ${skills ? `<div class="res-hero-skills">${skills}</div>` : ""}
      </div>
    </div>`;
}

function renderGarrison(sd) {
  const cards = sortedLevels(sd.levels).map(lv => {
    const conf = sd.levels[lv];
    const kinds = sd.npc[conf.npcLevel] || {};
    const kindKeys = Object.keys(kinds).sort((a, b) => a - b);

    const soldierChips = kindKeys.map(k => {
      const f = kinds[k];
      const soldier = data.soldiers[f.sType];
      return `<span class="res-soldier kind-${k}">${escapeHtml(soldier ? str(soldier.name) : SOLDIER_KIND_LABELS[k])}<b>${num(f.sCnt)}</b></span>`;
    }).join("");

    // 各兵種的守將通常相同，相同時只列一次
    const heroSets = [...new Set(kindKeys.map(k => kinds[k].heroes.join(",")))];
    const heroHtml = heroSets.map(set => {
      const owners = heroSets.length > 1
        ? `<div class="res-hero-owner">${kindKeys.filter(k => kinds[k].heroes.join(",") === set).map(k => SOLDIER_KIND_LABELS[k] + "兵").join("、")}</div>`
        : "";
      const heroes = groupHeroes(sd, set.split(",")).map(g => renderHero(g.hero, g.slots)).join("");
      return owners + heroes;
    }).join("");

    return `
      <article class="res-card">
        <header class="res-card-head">
          <span class="res-card-lv">Lv.${lv}</span>
          <span class="res-card-troops">守軍 <b>${conf.troops}</b> 隊</span>
          <span class="res-card-spacer"></span>
          <span class="res-card-meta">體力 ${conf.energy} · 經驗 ${num(conf.exp)}</span>
        </header>
        <div class="res-row">
          <span class="res-label">每隊兵力</span>
          <div class="res-soldiers">${soldierChips}</div>
        </div>
        <div class="res-row res-row-heroes">
          <span class="res-label">守將</span>
          <div class="res-heroes">${heroHtml}</div>
        </div>
        <div class="res-recommend">
          推薦 · 兵力 <b>${num(conf.recommendTroops)}</b> · 武將 <b>Lv.${conf.recommendHeroLevel}</b>
          · 技能 <b>Lv.${conf.recommendSkillLevel}</b>${conf.recommendWeaponLevel ? ` · 專武強化 <b>${conf.recommendWeaponLevel}</b>` : ""}
        </div>
      </article>`;
  }).join("");
  $("resGarrison").innerHTML = cards;
}

function renderAll() {
  const sd = data.seasons[season] || data.seasons[DEFAULT_SEASON];
  renderProduction(sd);
  renderGarrison(sd);
}

/** 產出表折疊：記住使用者的展開 / 收合狀態，收合時在標題旁顯示提示 */
function bindProductionCollapse() {
  const panel = $("resProductionPanel");
  try {
    const saved = localStorage.getItem(PRODUCTION_OPEN_KEY);
    if (saved !== null) panel.open = saved === "1";
  } catch { /* 無法存取 storage 時維持預設展開 */ }
  const sync = () => { $("resProductionHint").textContent = panel.open ? "" : "點擊展開"; };
  sync();
  panel.addEventListener("toggle", () => {
    sync();
    try { localStorage.setItem(PRODUCTION_OPEN_KEY, panel.open ? "1" : "0"); } catch { /* 忽略 */ }
  });
}

/** 第一次切換到資源地頁時載入資料並渲染（之後重複呼叫不做事） */
export function initResource() {
  if (loading) return loading;
  bindProductionCollapse();
  loading = (async () => {
    try {
      const res = await fetch("data/resource_ground.json");
      if (!res.ok) throw new Error("HTTP " + res.status);
      data = await res.json();
      if (!data.seasons[season]) season = DEFAULT_SEASON;
      $("resLoading").hidden = true;
      renderSeasonChips();
      renderAll();
    } catch (err) {
      $("resLoading").textContent = "資源地資料載入失敗：" + err.message;
      console.error(err);
    }
  })();
  return loading;
}
